	@Test
	void pinsLmdbEpochAndExactProbesAcrossCommit(@TempDir File dataDir) throws Exception {
		try (TripleStore tripleStore = new TripleStore(dataDir, new LmdbStoreConfig("spoc,posc"), null)) {
			tripleStore.startTransaction();
			assertTrue(tripleStore.storeTriple(11L, 22L, 33L, 44L, true));
			tripleStore.commit();

			Class<?> sourceType = Class.forName("org.eclipse.rdf4j.sail.lmdb.LmdbFrontierSnapshotSource");
			Constructor<?> constructor = sourceType.getDeclaredConstructor(TripleStore.class);
			Method snapshotEpoch = sourceType.getDeclaredMethod("snapshotEpoch");
			Method contains = sourceType.getDeclaredMethod("contains", long.class, long.class, long.class,
					long.class, boolean.class);

			try (AutoCloseable pinnedSource = (AutoCloseable) constructor.newInstance(tripleStore)) {
				long pinnedEpoch = (long) snapshotEpoch.invoke(pinnedSource);
				assertTrue((boolean) contains.invoke(pinnedSource, 11L, 22L, 33L, 44L, true));
				assertFalse((boolean) contains.invoke(pinnedSource, 55L, 66L, 77L, 88L, true));

				tripleStore.startTransaction();
				assertTrue(tripleStore.storeTriple(55L, 66L, 77L, 88L, true));
				tripleStore.commit();

				assertEquals(pinnedEpoch, snapshotEpoch.invoke(pinnedSource));
				assertTrue((boolean) contains.invoke(pinnedSource, 11L, 22L, 33L, 44L, true));
				assertFalse((boolean) contains.invoke(pinnedSource, 55L, 66L, 77L, 88L, true));

				try (AutoCloseable currentSource = (AutoCloseable) constructor.newInstance(tripleStore)) {
					assertNotEquals(pinnedEpoch, snapshotEpoch.invoke(currentSource));
					assertTrue((boolean) contains.invoke(currentSource, 55L, 66L, 77L, 88L, true));
				}
			}
		}
	}

