	@Test
	void callbackFailureClosesIteratorWhileTxnReadLockIsActive(@TempDir File dataDir) throws Exception {
		try (CloseLockObservingTripleStore tripleStore = new CloseLockObservingTripleStore(dataDir)) {
			Class<?> sourceType = Class.forName("org.eclipse.rdf4j.sail.lmdb.LmdbFrontierSnapshotSource");
			Class<?> sinkType = Class.forName("org.eclipse.rdf4j.sail.lmdb.LmdbFrontierSnapshotSource$RawQuadSink");
			Constructor<?> constructor = sourceType.getDeclaredConstructor(TripleStore.class);
			Method scan = sourceType.getDeclaredMethod("scan", boolean.class, sinkType);
			Object failingSink = Proxy.newProxyInstance(sinkType.getClassLoader(), new Class<?>[] { sinkType },
					(proxy, method, args) -> {
						if ("accept".equals(method.getName())) {
							throw new IOException("intentional callback failure");
						}
						throw new AssertionError("Unexpected RawQuadSink method: " + method);
					});

			try (AutoCloseable source = (AutoCloseable) constructor.newInstance(tripleStore)) {
				InvocationTargetException failure = assertThrows(InvocationTargetException.class,
						() -> scan.invoke(source, true, failingSink));

				IOException callbackFailure = assertInstanceOf(IOException.class, failure.getCause());
				assertEquals("intentional callback failure", callbackFailure.getMessage());
				assertTrue(tripleStore.iteratorCloseCalled());
				assertFalse(tripleStore.iteratorCloseAcquiredWriteLock());
			}
		}
	}

